import os
BASE = r'D:\Seed'

# Fix types/index.ts Role type
tp = os.path.join(BASE, 'src/types/index.ts')
with open(tp, 'r', encoding='utf-8') as f: c = f.read()
c = c.replace("export type Role = 'admin' | 'moderator' | 'soul' | 'observer' | 'anonymous';", "export type Role = 'admin' | 'soul' | 'observer';")
c = c.replace("export type ServerRole = 'admin' | 'moderator' | 'soul' | 'observer' | 'anonymous';", "export type ServerRole = 'admin' | 'soul' | 'observer';")
with open(tp, 'w', encoding='utf-8', newline='\n') as f: f.write(c)
print('FIXED types/index.ts')

# Write correct server.ts
server = "// HTTP + WebSocket server for Seed.\nimport express, { type Request, type Response } from 'express';\nimport { WebSocketServer, type WebSocket } from 'ws';\nimport { createServer } from 'node:http';\nimport { WorldEngine } from '../engine/WorldEngine.js';\nimport { InputValidator } from '../security/InputValidator.js';\nimport { PermissionSystem } from '../security/PermissionSystem.js';\nimport { RateLimiter } from '../security/RateLimiter.js';\nimport { apiKeyAuth } from '../security/ApiKeyAuth.js';\nimport { sanitizeString } from '../security/sanitize.js';\nimport { SoulClient } from './soulClient.js';\nimport { Logger } from '../reliability/Logger.js';\nconst log = Logger.for('api');\nexport interface ServerDeps { engine: WorldEngine; soulClient: SoulClient; port?: number; }\nconst actionValidator = new InputValidator();\nconst permissions = new PermissionSystem();\nconst limiter = new RateLimiter(100);\nexport function createApp(deps: ServerDeps) {\n  const app = express();\n  app.use(express.json({ limit: '256kb' }));\n  app.use(apiKeyAuth({ enabled: process.env.SEED_AUTH === 'on', validKeys: (process.env.SEED_API_KEYS ?? 'dev-seed-key').split(',') }));\n  app.get('/api/world/status', (_req: Request, res: Response) => { const w = deps.engine.currentWorld; res.json({ world: w?.config.name ?? null, running: deps.engine.isRunning, tick: w?.tick ?? 0, worldTime: w?.worldTime ?? 0, entityCount: w?.entities.size ?? 0 }); });\n  app.get('/api/entities', (_req: Request, res: Response) => { const w = deps.engine.currentWorld; if (!w) return res.json({ entities: [] }); res.json({ entities: [...w.entities.values()].map((e) => e.toJSON()) }); });\n  app.get('/api/entities/:id', (req: Request, res: Response) => { const e = deps.engine.currentWorld?.getEntity(req.params.id); if (!e) return res.status(404).json({ error: 'not_found' }); res.json({ entity: e.toJSON() }); });\n  app.post('/api/entities', (req: Request, res: Response) => { const w = deps.engine.currentWorld; if (!w) return res.status(503).json({ error: 'no_world' }); const result = actionValidator.validate({ name: { type: 'string', required: true, max: 64 }, x: { type: 'number', required: true }, y: { type: 'number', required: true }, z: { type: 'number', required: true } }, req.body); if (!result.ok) return res.status(400).json({ error: 'validation_failed', errors: result.errors }); res.status(201).json({ ok: true, note: 'entity creation via SDK; see docs/SDK.md' }); });\n  app.post('/api/souls/:id/action', (req: Request, res: Response) => { const w = deps.engine.currentWorld; if (!w) return res.status(503).json({ error: 'no_world' }); const clientId = req.ip ?? 'anonymous'; const rl = limiter.check(clientId); if (!rl.allowed) return res.status(429).json({ error: 'rate_limited', retryAfterMs: rl.retryAfterMs }); const result = actionValidator.validate({ action: { type: 'string', required: true, enum: ['move', 'speak', 'interact', 'attack', 'use'] }, payload: { type: 'object', required: false } }, req.body); if (!result.ok) return res.status(400).json({ error: 'validation_failed', errors: result.errors }); const proxyId = `soul_${req.params.id}`; const proxy = w.getEntity(proxyId); if (!proxy) return res.status(404).json({ error: 'soul_not_in_world', soulId: req.params.id }); permissions.ensure('soul', 'entity', 'interact'); const action = String((result.value as { action: string }).action); if (action === 'speak') { const text = sanitizeString(String((result.value as { payload?: { text?: string } }).payload?.text ?? '')); log.info({ soulId: req.params.id, text }, 'soul speak'); } res.json({ ok: true, action, soulId: req.params.id, tick: w.tick }); });\n  app.get('/api/souls', async (_req: Request, res: Response) => { const { souls, usedMock } = await deps.soulClient.listSouls(); res.json({ souls, source: usedMock ? 'mock' : 'soul-arena' }); });\n  return app;\n}\nexport async function startServer(deps: ServerDeps): Promise<{ close: () => void }> {\n  const port = deps.port ?? Number(process.env.PORT ?? 3100);\n  const app = createApp(deps);\n  const httpServer = createServer(app);\n  const wss = new WebSocketServer({ server: httpServer, path: '/ws' });\n  wss.on('connection', (socket: WebSocket) => { log.info('ws client connected'); socket.send(JSON.stringify({ type: 'hello', payload: { protocol: 'seed-soul', version: '0.1.0' }, timestamp: Date.now() })); socket.on('message', (raw) => { try { const msg = JSON.parse(raw.toString()) as { type: string; payload?: unknown; soulId?: string }; log.info({ type: msg.type, soulId: msg.soulId }, 'ws message'); socket.send(JSON.stringify({ type: 'ack', payload: { echo: msg.type }, timestamp: Date.now() })); } catch (err) { socket.send(JSON.stringify({ type: 'error', payload: { message: 'invalid json' }, timestamp: Date.now() })); } }); });\n  await new Promise<void>((resolve) => httpServer.listen(port, () => { log.info({ port }, 'Seed API listening'); resolve(); }));\n  return { close: () => { wss.close(); httpServer.close(); } };\n}\n"
sp = os.path.join(BASE, 'src/api/server.ts')
with open(sp, 'w', encoding='utf-8', newline='\n') as f: f.write(server)
print('WROTE server.ts')
print('DONE p5')
